function head(){return `<div class="tg75-note" role="status">${esc(bridge.current().message)}${!online()?'<p>Prévia: nenhuma disputa, votação, premiação ou transferência pode ser executada.</p>':''}</div>${card('Festival selecionado',snap?`<strong>${esc(snap.festival.title)}</strong><p>${esc(snap.festival.state)} · ${esc(snap.festival.participants_count)} competidores · versão ${esc(version())}</p>${btn('Atualizar','refresh',{},'local')}`:empty('Nenhum festival selecionado'))}`;}
function inicio(){return head()+card('Criar festival',`<form id="tg08-create"><label>Nome<input name="title" minlength="3" maxlength="120" required></label><button class="tg75-button" ${!online()?'disabled':''}>Criar festival</button></form>`)+card('Entrar em festival',`<form id="tg08-join"><label>Código do festival<input name="festival_id" required placeholder="UUID recebido"></label><label>Nome de palco<input name="name" maxlength="70" required></label><label>Papel<select name="role"><option value="competitor">Competidor</option><option value="spectator">Plateia</option><option value="guest_voter">Votante temporário</option></select></label><button class="tg75-button" ${!online()?'disabled':''}>Solicitar participação</button></form>`)+card('Meus festivais',festivals.length?festivals.map(f=>`<p>${esc(f.title)} · ${esc(f.state)} ${btn('Abrir','select',{id:f.id},'local')}</p>`).join(''):empty('Nenhum festival disponível.'))+(ctrl()?card('Ciclo do festival',(['registration','qualifying','bracket'].includes(state())?reasonForm('Salvar e entrar em intervalo','save_battle',{},'lifecycle'):'')+(state()==='intermission'?reasonForm('Retomar após reconfirmação','resume_battle',{},'lifecycle'):'')+(!['completed','cancelled'].includes(state())?reasonForm('Preparar encerramento definitivo','prepare_cancel',{},'lifecycle'):'')+(cancelIntent?`<p>Encerramento preparado; não altera o estado até a confirmação final.</p>${btn('Confirmar encerramento sem conclusão','cancel_battle',{confirmation_id:cancelIntent.id},'lifecycle')}`:'')+mfaNote()):'');}
// R74 — contrato SQL35 instalado. Sem autoridade local sobre sorteio, fila ou nota.
