content.addEventListener('change',e=>{if(online()||dialog.dataset.tg33Mode!=='preview')return;const t=e.target,d=tg68Demo;if(t.matches('[data-tg68-count]')&&!d.locked){const n=Number(t.value);if(Number.isInteger(n)&&n>=2&&n<=12){d.n=n;render();}}else if(t.matches('[data-tg68-track]')&&!d.locked){const i=Number(t.dataset.tg68Track);if(Number.isInteger(i)&&i>=0&&i<13){if(t.checked)d.selected.add(i);else d.selected.delete(i);render();}}else if(t.matches('[data-tg68-personal]')&&d.locked){const v=t.value;if(v===''||(/^\d+$/.test(v)&&Number(v)<tg68Tracks.length)){d.personal=v;d.drawn=[];render();}}});
dialog.addEventListener('click',async e=>{const demoButton=e.target.closest('[data-tg68-lock],[data-tg68-reset],[data-tg68-draw]');if(demoButton){if(online()||dialog.dataset.tg33Mode!=='preview'||demoButton.disabled)return;const d=tg68Demo;if(demoButton.matches('[data-tg68-reset]'))tg68Demo=tg68New();else if(demoButton.matches('[data-tg68-lock]')){const min=tg68Minimum();if(!d.locked&&min!==null&&d.selected.size>=min)d.locked=true;}else if(demoButton.matches('[data-tg68-draw]')&&d.locked&&d.personal!==''){const remaining=[...d.selected].filter(x=>!d.drawn.includes(x));if(remaining.length)d.drawn.push(remaining[crypto.getRandomValues(new Uint32Array(1))[0]%remaining.length]);}render();return;}const profileButton=e.target.closest('#tg63-voter-profile');if(profileButton){if(!profileButton.disabled&&voterView()&&!busy&&uid===ctx()?.getUser()?.id){const user=ctx()?.getUser();if(user?.is_anonymous===true||user?.app_metadata?.provider==='anonymous')selectTab('inicio');else window.TG_BETA_OPEN_TAB?.('profile');}return;}if(e.target.closest('[data-r62-voter-back]')){if(!busy&&voterView()){musicReset();reloadSeq++;festivalId=null;snap=null;voteVerifiedAt=null;tab='inicio';render();}return;}const personal=e.target.closest('[data-tg77-go-personal]');if(personal){if(!busy&&online()&&ownCompetitor())selectTab('classificatoria');return;}const t=e.target.closest('[data-tg75-tab]');if(t){selectTab(t.dataset.tg75Tab);return;}const b=e.target.closest('[data-action]');if(!b||b.disabled||busy)return;const name=b.dataset.action;let p=payload(b);const l=lease();if(api.MFA.has(name)&&!await window.TG_UI.confirm('Esta ação é crítica e ficará registrada. Confirma?',{title:'Confirmação de segurança',confirmText:'Confirmar',danger:true}))return;if(!liveLease(l)||!b.isConnected)return;void invoke(name,p,b.dataset.kind,l);});
content.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(busy||!online())return;const d=new FormData(f);if(f.id==='tg74-music-search')return void invoke('music_search',{query:String(d.get('query')||''),page:0},'local');if(f.id==='tg08-create')return void invoke('create',{title:d.get('title')});if(f.id==='tg08-join')return void invoke('join',{festival_id:d.get('festival_id'),name:d.get('name'),role:d.get('role')});if(f.dataset.vote)return void invoke('cast_vote',{window_id:f.dataset.vote,stars_a:Number(d.get('stars_a')),stars_b:d.has('stars_b')?Number(d.get('stars_b')):null});if(f.id==='tg08-mfa-form'){busy=true;try{const level=await bridge.verify(f.dataset.factor,String(d.get('code')));factor=null;render();message(level==='aal2'?'MFA validado com sucesso.':'Validação pendente.');}catch(err){message(err.message);}finally{busy=false;}return;}if(f.dataset.reasonAction){const name=f.dataset.reasonAction,p={...payload(f),reason:String(d.get('reason')||'')},l=lease();if(api.MFA.has(name)&&!await window.TG_UI.confirm('Confirma esta ação crítica e sua justificativa?',{title:'Confirmação de segurança',confirmText:'Confirmar',danger:true}))return;if(!liveLease(l)||!f.isConnected)return;void invoke(name,p,f.dataset.kind,l);}});
